-- GENERATED by `wfj generate` from data/gossip/gossip-95.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["9504c07d83234d64"] = { "Il maestro Nesingwary ha una grande caccia davanti a sé. Trovo che aiutarlo a prepararsi per una giornata nella giungla sia molto più rilassante che aiutarlo a prepararsi al combattimento. Anche se mi mancano alcuni di quei momenti gloriosi sul campo di battaglia.", "." },
  ["95062a863bb6ca1f"] = { "Ottimo lavoro, tutti quanti! Il Flagello nel castello è stato sconfitto.", "." },
  ["9514cfda25ca2fb3"] = { "Uccidetela! Prendete la fattoria!", "." },
  ["952031770d5eefb4"] = { "Per la Luce! Non va per niente bene. C'è qualcosa che non capisci, {name}.", "." },
  ["9521b42d8c75c952"] = { "Aaahh... Molto bene. Ora sparisci!", "." },
  ["952de74b1700a45d"] = { "Banca in torre centrale di ⟦Trade Quarter=Quartiere del Commercio⟧. Tu non sbagliare.", "." },
  ["953e6ce354a923c1"] = { "Tenermi qui non è la decisione giusta, Marcus.", "." },
  ["9540e9b4afe0f727"] = { "E lo trovò davvero. Dopo una rapida ascesa nei ranghi del Culto, il Re dei Lich in persona concesse a Ras l'immortalità. Così nacque ⟦Ras Frostwhisper=Ras Soffiogelo⟧, il lich.\n\nOra capisci?", "." },
  ["95436ddf36b44d0a"] = { "Arrivo, Lupi Bianchi, e stavolta assaggerete le fiamme!", "." },
  ["9545778d1e33ac73"] = { "Non è molto sicuro andarsene in giro per i boschi, {name}. Sta' attent<o/a>, e se vedi qualcosa di sospetto o pericoloso, avverti subito i Guardiani. Non provare ad affrontare niente da sol<o/a>. Non siamo responsabili di qualunque cosa terribile possa capitarti.\n\nMa sappiamo entrambi che mi ignorerai e combatterai comunque qualunque cosa esca dall'oscurità, vero? Ah ah, già, voi avventurieri... tutti uguali.", "." },
  ["95465e3244aae924"] = { "Giornataccia? Una bella birra ti scioglierà subito le preoccupazioni.", "." },
  ["954731e03afd7456"] = { "%s beve un lungo sorso di birra.", "." },
  ["95478347908da4b4"] = { "Il palo è coperto dei resti di chi è stato tanto sciocco da far infuriare il Capoguerra.", "." },
  ["954c3f43a9596466"] = { "Anche se il ⟦Crossroads=Crocevia⟧ sembra il centro di ogni attività nelle ⟦The Barrens=Savane⟧, preferisco la quiete di Camp Taurajo. Dove vuoi che ti mandi?", "." },
  ["954e33b7c095f26b"] = { "Il vincitore della gara di velocità è... la squadra degli gnomi! Ottimo lavoro, ragazzi!", "." },
  ["95502afc2330d09d"] = { "Per favore, mostrami la Stone of Maraudon.", "." },
  ["9556ee0baa43361d"] = { "Ho un messaggio speciale per {name}. E dice che devi morire!", "." },
  ["955b79c824df3898"] = { "Non mettiamoci nemmeno a confrontare le cicatrici di guerra, amico mio.", "." },
  ["955bcc06a5f37ba1"] = { "Mi hai mostrato il tuo desiderio e hai pagato con pietre preziose. Ti insegnerò...", "." },
  ["955f3fe100c510cd"] = { "Quel ⟦Jormund Stonebrow=Jormund Cigliadure⟧ ci sa fare con l'ago, eccome. Se ti serve un addestramento, lo trovi da Stonebrow's Clothier, sul lato nord della ⟦Great Forge=Grande Forgia⟧.", "." },
  ["95654529a05d1f19"] = { "Proprio mentre parliamo, {class}, tutto il materiale bellico viene trasportato a ⟦Silithus=Silitus⟧. A quanto pare, l'ultimo carico dovrebbe arrivare in meno di un giorno. Dopodiché, servirà che qualche <eroe/eroina> venga a suonare il gong all'Altare dello Scarabeo. Allora la guerra comincerà davvero.", "." },
  ["9566e8d06fc4d743"] = { "Ci guiderò attraverso Valsalda fino al limitare della foresta. Da lì, mi porterai da mio padre.", "." },
  ["9569fa1a841cf422"] = { "Ti prego, aiutami, <fratello/sorella>...\n\nPresto lascerò questo mondo, e anche se soffro, so che dopo il trapasso non soffrirò più. Ma la fauna, <fratello/sorella> <mio/mia>... anche la fauna soffre, e non conosce sollievo. Ti chiedo aiuto con gli ultimi respiri della mia vita.", "." },
  ["956aba84fd18d0e9"] = { "Lo SPACCHIAMO CON UN MARTELLO!", "." },
  ["9579ce3e559801e4"] = { "%s emette uno strano rumore.", "." },
  ["957ceb2e3b88063e"] = { "Sì, Fandral, ricorda queste parole: non lasciare che il dolore guidi la tua fede. Questi pensieri che coltivi... luoghi oscuri in cui vai, elfo della notte. L'assoluzione non si ottiene con una vendetta sconsiderata.", "." },
  ["958100a8e1bc2d4d"] = { "Dov'è la ⟦Silver Hand=Mano d'Argento⟧? Ci serve il suo aiuto!", "." },
  ["958877ca7f63a315"] = { "Orrendi muggiti e ringhi provengono dalla baracca di quel vecchio eremita!", "." },
  ["9589a9e3e8eccf49"] = { "Aiutate i bambini di ⟦Stormwind=Roccavento⟧... vittime della guerra e della peste!", "." },
  ["958c9f67a04f8df2"] = { "Stregone", "." },
  ["95916e3c7f1be40d"] = { "Sentire puzza brutta vicino. Me sentire te puzza brutta.", "." },
  ["9593cf89f72bab46"] = { "Oggi la schiena mi sta uccidendo.", "." },
  ["959522b13d831fdc"] = { "Presentati all'immagine dell'arcimago Modera, vicino alla città di Dalaran.", "." },
  ["9596a2dd51f925cf"] = { "Mi serve aiuto per recuperare un pezzo mancante dei miei abiti da aruspice, Maywiki.", "." },
  ["959ae07152a8b82b"] = { "Ben ritrovat<o/a>, {name}. Hai un bell'aspetto.\n\nCosa ti riporta da me così presto?", "." },
  ["959f27613d5af873"] = { "Ehi, eccone uno!", "." },
  ["95a312df7baa87a8"] = { "Dov'è l'anziano Malatomba?", "." },
  ["95a5244834da6e71"] = { "Ah, uno dei miei clienti preferiti. Hai l'aria di <uno/una> <stregone/strega> di un certo potere, {name}. È un piacere conoscerti. Se c'è qualcosa che posso fare per te, ti prego, chiedi pure.\n\nMio fratello e io pensiamo che saranno quelli come te a guidarci nella prossima grande era. Un tale potere... un tale controllo... è solo questione di tempo prima che la Legione stessa si pieghi alla tua volontà.\n\nNon nascondo un pizzico d'invidia.", "." },
  ["95aeb2482dc5ecfd"] = { "I nostri veterani lasciano il campo. Ci servono altre provviste!", "." },
  ["95bccce13c608720"] = { "Il tempo della guerra è quasi giunto, {class}! Sia l'⟦Horde=Orda⟧ sia l'⟦Alliance=Alleanza⟧ hanno completato i preparativi. Tutto il nostro materiale bellico viene spedito a ⟦Silithus=Silitus⟧ proprio ora. Mi aspetto che arrivi tutto entro $2113w giorni. Quando tutto sarà radunato là, chi avrà portato a termine l'arduo compito di ricomporre lo Scettro delle Sabbie Mutevoli lo batterà contro lo Scarab Gong e aprirà i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Allora si combatterà una battaglia come non se ne vedevano da secoli!\n\nLok'tar Ogar!", "." },
  ["95c42a96ddd37f7a"] = { "Che devastazione... che disastro orribile...", "." },
  ["95cdc6898d910068"] = { "Attraverso la gemma, Elune incanalò la sua infinita saggezza...", "." },
  ["95cf11f3d17d7724"] = { "Amakkar, dove credi che ci manderà il signore della guerra Zannatruce? Non credo di reggere un altro turno nelle Steppe.", "." },
  ["95d11ba6baa6cf5e"] = { "Non ho mai detto che fossi qui per la tua redenzione, <sacerdote/sacerdotessa>. Sei qui per redimere me e gli innocenti assassinati mentre cercavano di fuggire da Stratholme.\n\nIl mio spirito e quello di chi è perito sono legati a questo luogo, condannati a rivivere senza fine le nostre tragiche morti.", "." },
  ["95d2efac7669eccf"] = { "%s inizia a evocare dei guardiani!", "." },
  ["95d9c10cb1230f8e"] = { "È così emozionante essere qui a Darnassus, in mezzo a gente di talento! So che renderò fiera la mia famiglia. Magari, con un po' di fortuna, le ⟦Sentinels=Sentinelle⟧ mi chiederanno di unirmi alle loro forze al fronte!", "." },
  ["95de5985916df9d9"] = { "PER L'ORDA! PER CAIRNE! PER PICCO DEL TUONO!", "." },
  ["95dfee2f5ab50051"] = { "Il titolo è fuorviante. In realtà sono una persona molto simpatica, quando mi si conosce.", "." },
  ["95e080a164b446ed"] = { "Non guardare mai il comandante dritto negli occhi.", "." },
  ["95e22a4df1371271"] = { "La tribù dei Selvanera sta profanando le nostre terre sacre.", "." },
  ["95e850f06dc8c65c"] = { "Mi deludi, Taelan. Avevo dei piani per te... grandi piani. Ahimè, era solo questione di tempo prima che il tuo sudicio sangue venisse a galla.", "." },
  ["95f02c52525afc3f"] = { "Allora... hai fatto fuori il re, eh? Lo sapevo che questi babbei ti avrebbero fatto <nuovo/nuova> <re/regina>, lo sapevo e basta! È l'unica cosa che questi babbei capiscono: il potere.\n\nSembra che più scagnozzi tieni in vita, più alto sarà il tuo tributo. Niente male: una bella sfida, direi. Se te ne vai, non aspettarti di restare <re/regina>. Uno di questi zotici si farà avanti di sicuro per prendere il tuo posto.\n\nUn'ultima cosa... non è che per caso hai trovato la mia chiave?", "." },
})
